import java.util.*;

public class Main {
    int minOperations(String[] logs) {
        Deque<String> stack = new ArrayDeque<>();                                    // a stack of folder names actually models the real file system
        for (String log : logs) {
            if (log.equals("../")) {
                if (!stack.isEmpty()) stack.pop();                                       // go up, if not already at the root
            } else if (log.equals("./")) {
                // stay in place
            } else {
                stack.push(log);                                                          // enter a named child folder
            }
        }
        return stack.size();                                                              // the stack's size IS the current depth
    }

    public static void main(String[] args) {
        Main solution = new Main();
        String[] logs = {"d1/", "d2/", "../", "d21/", "./"};
        System.out.println(solution.minOperations(logs));
    }
}

